source_by_cat = {
"웹 UI·UX":"https://github.com/nextlevelbuilder/ui-ux-pro-max-skill","프론트엔드":"https://github.com/anthropics/skills","바이브코딩":"https://github.com/anthropics/skills","프롬프트 설계":"https://platform.openai.com/docs/guides/prompt-engineering","인스타그램":"https://www.instagram.com/creators/","유튜브":"https://support.google.com/youtube/","숏폼 영상":"https://support.google.com/youtube/","SEO·검색":"https://developers.google.com/search/docs","노코드·자동화":"https://n8n.io/workflows/","나머지":"https://github.com/anthropics/skills"}

def source(cat):
    return source_by_cat.get(cat, source_by_cat["나머지"])

def make(i, cat, title, j):
    slug = f"playbook-{i:03d}-{j+1}"
    compatible = ["ChatGPT", "Claude", "Manus", "Antigravity", "Codex"]
    if cat in {"인스타그램", "유튜브", "숏폼 영상", "영상 제작"}: compatible += ["Gemini", "Canva"]
    if cat in {"웹 UI·UX", "프론트엔드", "바이브코딩"}: compatible += ["Cursor", "Windsurf"]
    return {"id": i, "name": title, "slug": slug, "category": cat, "summary": f"{cat}에서 {title}을 반복 가능한 작업 흐름으로 만드는 실전 플레이북", "guide": f"{title}은 {cat} 작업에서 목표와 입력 자료를 정리하고 AI에게 초안·변형·검수 기준을 요청하는 스킬입니다. 인스타그램·유튜브 같은 채널에서는 조회수 자체를 보장한다고 표현하지 않고, 타깃·메시지·실험 결과를 기록하며 개선하는 용도로 사용합니다.", "howTo": "목표와 대상 독자를 먼저 적고, 참고 자료·원하는 형식·금지사항·사람이 확인할 지점을 함께 입력합니다. 결과를 한 번에 게시하지 말고 2~3개 변형을 비교한 뒤 선택하세요.", "example": f"“{title}을 사용해 초보자도 따라 할 수 있는 결과물 3개를 만들고, 각 결과물의 장점·위험·검수 체크리스트를 함께 보여줘.”", "compatible": compatible, "license": "플레이북·라이선스 확인 필요", "licenseNote": "관련 서비스·원문 저장소의 사용 조건을 확인한 뒤 적용", "source": "AI/100 practice playbook", "sourceUrl": source(cat), "importUrl": "", "verifiedAt": "2026-08-21", "tags": [cat, "실전 플레이북", "검수 필요"]}

items=[]
for cat, titles in families:
    for j,title in enumerate(titles): items.append(make(len(items)+1, cat, title, j))
assert len(items)==300
out=Path('/home/ubuntu/ai-tools-directory/client/src/lib/skills300.ts')
out.write_text('''import type { SkillEntry } from "./skills";\n\n// GitHub verified skill과 구분되는 AI/100 실전 플레이북 300개입니다. 조회수·인기도를 보장하지 않으며 원문·서비스 정책을 확인하세요.\nexport const skills300: SkillEntry[] = '''+json.dumps(items, ensure_ascii=False, indent=2)+';\n')
print(f'generated {len(items)} practice playbooks')
